 function renderInventory(){const el=document.querySelector('#items');el.innerHTML='';const keys=Object.keys(inventory).filter(k=>inventory[k]>0);keys.slice(0,4).forEach(k=>{const s=document.createElement('div');s.className='item-slot';s.title=inventoryLabels[k][1];s.innerHTML=inventoryLabels[k][0]+'<em>'+inventory[k]+'</em>';el.appendChild(s)});while(el.children.length<4){const s=document.createElement('div');s.className='item-slot';s.style.opacity='.45';s.innerHTML='·';el.appendChild(s)}document.querySelector('#capacity').textContent=Object.values(inventory).reduce((a,b)=>a+b,0)+' / 12'}
 renderInventory();function updateBoot(){let b=bootTypes[bootIndex];document.querySelector('#boot-icon').textContent=b.icon;document.querySelector('#boot-name').textContent=b.name;document.querySelector('#boot-state').textContent=b.state}
 function setBiome(i){biomeIndex=i;let b=biomes[i];document.querySelector('#biome-title').textContent=b.name;document.querySelector('#biome-sub').textContent=b.sub;groundMat.color.set(b.ground);pathMat.color.set(b.path);scene.background.set(b.sky);scene.fog.color.set(b.sky);leafMats.forEach(m=>m.color.set(b.trees));document.querySelector('#progress-fill').style.width=(18+i*24)+'%';toast('Новый биом: '+b.name)}
 let toastTimer;function toast(t){const el=document.querySelector('#toast');el.textContent=t;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100)}
-function walk(){step++;const dist=Math.max(0,1240-step*13);document.querySelector('#distance').textContent=dist.toLocaleString('ru-RU')+' м';avatar.position.x=curveX(-step*.6)*.16;avatar.rotation.y=Math.sin(step*.12)*.06;camera.position.x=curveX(-step*.5)*.12;camera.lookAt(0,.8,-8);pathGroup.position.z=step*3.1;for(const p of pickups){if(p.got)continue;let rel=p.z+step*3.1;if(rel>-.2&&rel<2.8){p.got=true;scene.remove(p.mesh);scene.remove(p.halo);inventory[p.type]++;totalFound++;renderInventory();document.querySelector('#coin-count').textContent=24+Math.floor(totalFound/3)*2;toast('Найдено: '+p.name+'  +1')}}for(const o of scenery){o.position.z+=.13;if(o.position.z>12)o.position.z-=100}if(step===20||step===40||step===60)setBiome(Math.min(3,Math.floor(step/20)));if(dist===0){toast('Привал! Путь продолжается…');step=0}}
+function walk(){step++;const dist=Math.max(0,1240-step*13);document.querySelector('#distance').textContent=dist.toLocaleString('ru-RU')+' м';avatar.position.x=curveX(-step*.6)*.16;avatar.rotation.y=Math.sin(step*.12)*.06;camera.position.x=curveX(-step*.5)*.12;camera.lookAt(0,.8,-8);for(const mesh of pathMeshes){mesh.position.z+=3.1;if(mesh.position.z>10){mesh.position.z-=99.2;mesh.position.x=curveX(mesh.position.z+1.5)}}for(const p of pickups){if(p.got)continue;p.mesh.position.z+=3.1;p.halo.position.z+=3.1;if(p.mesh.position.z>-.2&&p.mesh.position.z<2.8){p.got=true;scene.remove(p.mesh);scene.remove(p.halo);inventory[p.type]++;totalFound++;renderInventory();document.querySelector('#coin-count').textContent=24+Math.floor(totalFound/3)*2;toast('Найдено: '+p.name+'  +1')}}for(const o of scenery){o.position.z+=3.1;if(o.position.z>12)o.position.z-=100}if(step===20||step===40||step===60)setBiome(Math.min(3,Math.floor(step/20)));if(dist===0){toast('Привал! Путь продолжается…');step=0}}
 document.querySelector('#walk-btn').addEventListener('click',walk);document.querySelector('#swap-btn').addEventListener('click',()=>{bootIndex=(bootIndex+1)%bootTypes.length;updateBoot();toast('Обувь сменена: '+bootTypes[bootIndex].name)});
 // Hold-to-walk works well on touchscreens; click is also supported.
 let walking;const walkBtn=document.querySelector('#walk-btn');walkBtn.addEventListener('pointerdown',e=>{if(e.pointerType==='mouse')return;walking=setInterval(walk,480)});['pointerup','pointerleave','pointercancel'].forEach(ev=>walkBtn.addEventListener(ev,()=>clearInterval(walking)));
 const recipes=[{id:'potion',name:'Травяной настой',desc:'Помогает восстановить силы в пути',cost:{herb:2,berry:1},icon:'🧪'},{id:'torch',name:'Походный факел',desc:'Свет в сумерках и тепло у костра',cost:{wood:2,herb:1},icon:'🔥'},{id:'boots',name:'Заплатать обувь',desc:'Кожаные ботинки прослужат дольше',cost:{leather:1,wood:1},icon:'🥾'}];

